/// Whether the game has reached the terminal state requested by a carrier send.
///
/// A populated snapshot needs a newly disk-loaded, spawned carrier. An empty snapshot is a
/// teardown command, and is acknowledged by a fresh status report showing the idle state.
/// Keeping this distinction in one pure predicate makes it difficult for the status text and
/// the timeout path to disagree about whether a restore actually succeeded.
fn carrier_send_reached_goal(
    carrier_expected: bool,
    state: u8,
    kinds: usize,
    spawned: bool,
    took_our_bytes: bool,
    fresh_report: bool,
) -> bool {
    if carrier_expected {
        state == 2 && spawned && took_our_bytes
    } else {
        state == 0 && kinds == 0 && !spawned && fresh_report
    }
}

/// The editor, ACMD source, exports, and user-facing timeline all use one-based game frames.
const FIRST_GAME_FRAME: u32 = 1;

/// Rebuild a linked ACMD source index and replace the previous snapshot only after the scan
/// succeeds. An empty successful index is meaningful: it means the source project no longer
/// defines any scripts, so retaining the old snapshot would keep deleted spans authoritative.
fn rebuild_linked_acmd_source_index(
    root: &Path,
    current: &mut Option<crate::acmd_src::SourceIndex>,
) -> anyhow::Result<bool> {
    let index = crate::acmd_src::SourceIndex::build(root)?;
    let has_scripts = index.script_count() > 0;
    *current = Some(index);
    Ok(has_scripts)
}

#[cfg(test)]
mod linked_acmd_index_tests {
    use super::rebuild_linked_acmd_source_index;
    use crate::acmd_src::SourceIndex;

    #[test]
    fn successful_empty_rescan_replaces_old_index_but_failed_rescan_keeps_it() {
        let old_root = tempfile::tempdir().unwrap();
        let empty_root = tempfile::tempdir().unwrap();
        let missing_root = old_root.path().join("deleted");
        let mut current = Some(SourceIndex {
            root: old_root.path().to_path_buf(),
            ..SourceIndex::default()
        });

        assert!(!rebuild_linked_acmd_source_index(empty_root.path(), &mut current).unwrap());
        assert_eq!(current.as_ref().unwrap().root, empty_root.path());
        assert_eq!(current.as_ref().unwrap().script_count(), 0);

        let replaced = current.clone();
        assert!(rebuild_linked_acmd_source_index(&missing_root, &mut current).is_err());
        assert_eq!(current.unwrap().root, replaced.unwrap().root);
    }
}

/// The primary editor is deliberately split into task-sized surfaces.  The underlying ACMD
/// model is still one move; this enum only controls which part of that model is in front of the
/// user at a time.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PrimaryEditorTab {
    Collisions,
    Hurtboxes,
    MotionState,
    AudioFeedback,
}

impl PrimaryEditorTab {
    fn title(self) -> &'static str {
        match self {
            Self::Collisions => "Collisions",
            Self::Hurtboxes => "Hurtboxes",
            Self::MotionState => "Motion & state",
            Self::AudioFeedback => "Sound & feedback",
        }
    }

    fn description(self) -> &'static str {
        match self {
            Self::Collisions => {
                "Attack, grab, detection, wind, throw-damage, and active-hitbox commands for the selected move."
            }
            Self::Hurtboxes => {
                "Parameter-defined hurtbox capsules, intangibility, invincibility, OFF states, and damage-reaction armor for the selected move."
            }
            Self::MotionState => {
                "Facing, velocity, kinetic, animation-timing, ground/air, and stored script-state commands from the move's game_ script."
            }
            Self::AudioFeedback => {
                "Sounds plus camera shake, controller rumble, and the supported animation controls from the move's sound_ and expression_ scripts."
            }
        }
    }
}

const VISUAL_EFFECTS_DESCRIPTION: &str =
    "Particle spawns, trails, model or screen colour changes, and effect-control commands from the selected move's effect_ script.";
const WORK_FLAGS_DESCRIPTION: &str =
    "Work flags are named on/off switches stored by the game for this fighter. Move and status scripts use them to remember or signal conditions such as enabling a combo or marking a move phase; the flag's authored name identifies its exact purpose.";

/// Main-editor section names always carry a plain-language explanation on the name itself.
/// Keeping that convention in helpers makes a bare, unexplained heading easy to spot in review.
fn editor_section_heading(ui: &mut Ui, title: &str, description: &str) {
    ui.heading(title).on_hover_text(description);
}

fn editor_subsection_heading(ui: &mut Ui, title: &str, description: &str) {
    ui.label(RichText::new(title).strong())
        .on_hover_text(description);
}

/// A heading for the resizable left sidebar. Unlike the main editor headings, this one must not
/// report its full text width as an intrinsic minimum when the sidebar is intentionally clipped.
fn sidebar_section_heading(ui: &mut Ui, title: &str, description: &str) {
    ui.add(egui::Label::new(RichText::new(title).heading()).truncate())
        .on_hover_text(description);
}

fn editor_section_heading_with_badge(
    ui: &mut Ui,
    title: &str,
    description: &str,
    badge_color: Color32,
    badge: &str,
) {
    ui.horizontal_wrapped(|ui| {
        editor_section_heading(ui, title, description);
        ui.colored_label(badge_color, badge)
            .on_hover_text(description);
    });
}

fn editor_command_subsection_heading(
    ui: &mut Ui,
    title: &str,
    description: &str,
    badge_color: Color32,
    badge: &str,
) {
    ui.horizontal_wrapped(|ui| {
        editor_subsection_heading(ui, title, description);
        ui.colored_label(badge_color, badge)
            .on_hover_text(description);
    });
}

fn editor_collapsing(
    ui: &mut Ui,
    title: &str,
    description: &str,
    add_contents: impl FnOnce(&mut Ui),
) {
    let response = ui.collapsing(title, add_contents);
    response.header_response.on_hover_text(description);
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum InspectorFocus {
    Primary,
    Effects,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum HistoryAction {
    Undo,
    Redo,
}

/// A session-only snapshot for the currently open move.  Scripts and edit records are stored as
/// JSON bytes because several of the deliberately lossless ACMD enums do not implement
/// `PartialEq`; serializing them also means the equality check sees raw source tokens exactly as
/// the export path does.
#[derive(Debug, Clone, PartialEq)]
struct EditSnapshot {
    hitboxes: Vec<Hitbox>,
    script: Vec<u8>,
    effect_script: Vec<u8>,
    effects: Vec<crate::data::EffectCall>,
    sound_script: Vec<u8>,
    expression_script: Vec<u8>,
    effect_call_edits: Option<Vec<u8>>,
    effect_call_full: Option<Vec<u8>>,
    effect_dropped_lines: Option<Vec<u8>>,
    effect_frame_residue: Option<Vec<u8>>,
    sound_script_edit: Option<Vec<u8>>,
    expression_script_edit: Option<Vec<u8>>,
    edit_record: Option<Vec<u8>>,
}

#[derive(Debug, Clone)]
struct HistoryEntry {
    label: String,
    before: EditSnapshot,
    after: EditSnapshot,
}

#[derive(Debug, Default)]
struct MoveEditHistory {
    undo: Vec<HistoryEntry>,
    redo: Vec<HistoryEntry>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TimelineCategory {
    Collisions,
    Hurtboxes,
    Effects,
    MotionState,
    AudioFeedback,
}

impl TimelineCategory {
    fn title(self) -> &'static str {
        match self {
            Self::Collisions => "Collisions",
            Self::Hurtboxes => "Hurtboxes",
            Self::Effects => "Visual effects",
            Self::MotionState => "Motion & state",
            Self::AudioFeedback => "Sound & feedback",
        }
    }

    fn description(self) -> &'static str {
        match self {
            Self::Collisions => {
                "Show or hide attack, grab, detection, wind, throw-damage, and active-hitbox events on the timeline."
            }
            Self::Hurtboxes => {
                "Show or hide hurtbox status, intangibility, invincibility, reset, and damage-reaction armor events on the timeline."
            }
            Self::Effects => "Show or hide visual-effect and effect-control events on the timeline.",
            Self::MotionState => {
                "Show or hide movement, kinetic, animation-timing, and stored state events on the timeline."
            }
            Self::AudioFeedback => {
                "Show or hide sound, camera, rumble, and expression animation events on the timeline."
            }
        }
    }
}

#[cfg(test)]
mod editor_section_copy_tests {
    use super::*;

    #[test]
    fn primary_editor_and_timeline_use_the_same_category_names() {
        for (tab, category) in [
            (PrimaryEditorTab::Collisions, TimelineCategory::Collisions),
            (PrimaryEditorTab::MotionState, TimelineCategory::MotionState),
            (
                PrimaryEditorTab::AudioFeedback,
                TimelineCategory::AudioFeedback,
            ),
        ] {
            assert_eq!(tab.title(), category.title());
            assert!(tab.description().split_whitespace().count() >= 8);
            assert!(category.description().split_whitespace().count() >= 8);
        }
        assert_eq!(PrimaryEditorTab::Hurtboxes.title(), "Hurtboxes");
        assert!(PrimaryEditorTab::Hurtboxes
            .description()
            .contains("damage-reaction armor"));
        assert_eq!(TimelineCategory::Hurtboxes.title(), "Hurtboxes");
        assert!(TimelineCategory::Hurtboxes
            .description()
            .contains("damage-reaction armor"));
        assert_eq!(TimelineCategory::Effects.title(), "Visual effects");
        assert!(VISUAL_EFFECTS_DESCRIPTION.split_whitespace().count() >= 8);
    }

    #[test]
    fn work_flags_help_defines_the_engine_term_in_plain_language() {
        assert!(WORK_FLAGS_DESCRIPTION.contains("named on/off switches"));
        assert!(WORK_FLAGS_DESCRIPTION.contains("remember or signal conditions"));
        assert!(WORK_FLAGS_DESCRIPTION.contains("authored name"));
    }
}

#[cfg(test)]
mod picker_state_tests {
    use super::*;

    #[test]
    fn effect_source_labels_use_translated_and_qualified_names() {
        assert_eq!(effect_source_label("effect/fighter/pickel"), "Steve");
        assert_eq!(effect_source_label("effect/system/common"), "Common");
        assert_eq!(effect_source_label("effect/system/item"), "Item");
        assert_eq!(
            effect_source_label("effect/assist/bomberman"),
            "Assist: Bomberman"
        );
        assert_eq!(effect_source_label("effect/boss/galleom"), "Boss: Galleom");
        assert_eq!(
            effect_source_label("effect/weapon/ice_climber"),
            "Weapon: Ice Climber"
        );
        assert_eq!(effect_source_label("effect/fighter/my_mod"), "My_mod");
    }

    #[test]
    fn search_restore_preserves_prior_state_and_opens_selected_key() {
        let mut before = BTreeMap::new();
        before.insert("closed".to_string(), false);
        before.insert("open".to_string(), true);

        let opened_during_search = BTreeSet::new();
        assert!(!restored_search_open(
            &before,
            &"closed".to_string(),
            None,
            &opened_during_search
        ));
        assert!(restored_search_open(
            &before,
            &"open".to_string(),
            None,
            &opened_during_search
        ));
        assert!(restored_search_open(
            &before,
            &"closed".to_string(),
            Some(&"closed".to_string()),
            &opened_during_search
        ));
        assert!(!restored_search_open(
            &before,
            &"new".to_string(),
            None,
            &opened_during_search
        ));
        let mut opened = BTreeSet::new();
        opened.insert("new".to_string());
        assert!(restored_search_open(
            &before,
            &"new".to_string(),
            None,
            &opened
        ));
    }

    #[test]
    fn selected_move_category_can_be_the_search_restore_exception() {
        use crate::move_kinds::MoveGroup;

        let mut before = BTreeMap::new();
        before.insert(MoveGroup::Jab, false);
        before.insert(MoveGroup::Special, true);
        let opened_during_search = BTreeSet::new();

        assert!(restored_search_open(
            &before,
            &MoveGroup::Jab,
            Some(&MoveGroup::Jab),
            &opened_during_search
        ));
        assert!(restored_search_open(
            &before,
            &MoveGroup::Special,
            None,
            &opened_during_search
        ));
        assert!(!restored_search_open(
            &before,
            &MoveGroup::Item,
            None,
            &opened_during_search
        ));
    }

    #[test]
    fn picker_scroll_heights_follow_available_space() {
        assert_eq!(adaptive_scroll_height(1_000.0, 0.5, 120.0, 520.0), 500.0);
        assert_eq!(adaptive_scroll_height(2_000.0, 0.5, 120.0, 520.0), 520.0);
        assert_eq!(adaptive_scroll_height(80.0, 0.5, 120.0, 520.0), 80.0);
    }

    #[test]
    fn compact_source_fields_grow_with_their_value_but_stay_bounded() {
        let short = compact_source_field_width_for_text(8.0);
        let long = compact_source_field_width_for_text(180.0);
        assert!(short >= COMPACT_SOURCE_FIELD_MIN_WIDTH);
        assert!(short < long);
        assert!(long <= COMPACT_SOURCE_FIELD_MAX_WIDTH);
    }

    #[test]
    fn compact_panel_limits_follow_content_without_forcing_extra_space() {
        assert_eq!(scrubber_panel_max_height(0, 500.0), 116.0);
        assert!(scrubber_panel_max_height(2, 500.0) < scrubber_panel_max_height(20, 500.0));
        assert_eq!(hitbox_selector_height(0, 800.0), 48.0);
        assert_eq!(hitbox_selector_height(2, 800.0), 56.0);
        assert_eq!(
            hitbox_selector_height(20, 800.0),
            HITBOX_SELECTOR_MAX_HEIGHT
        );
        assert_eq!(hitbox_selector_height(20, 200.0), 152.0);
    }

    #[test]
    fn fixed_panel_contents_cannot_expand_the_panel_frame() {
        egui::__run_test_ui(|ui| {
            let response = egui::Panel::left("fixed_panel_geometry_test")
                .exact_size(72.0)
                .show_inside(ui, |ui| {
                    show_fixed_panel_contents(ui, "fixed_panel_geometry_contents", |ui| {
                        ui.allocate_space(egui::vec2(400.0, 20.0));
                    });
                });
            assert!(
                response.response.rect.width() <= 72.1,
                "fixed panel expanded to {}",
                response.response.rect.width()
            );
        });
    }

    #[test]
    fn toolbar_overflow_cannot_expand_the_compact_editor_sidebar() {
        egui::__run_test_ui(|ui| {
            let response = egui::Panel::right("toolbar_panel_geometry_test")
                .default_size(72.0)
                .min_size(72.0)
                .resizable(true)
                .show_inside(ui, |ui| {
                    show_fixed_panel_contents(ui, "toolbar_panel_contents", |ui| {
                        ui.horizontal(|ui| {
                            for label in [
                                "Fetch source",
                                "⟳ Live",
                                "Forget capture",
                                "Restore move",
                                "Undo",
                                "Redo",
                            ] {
                                let _ = ui.button(label);
                            }
                        });
                    });
                });
            assert!(
                response.response.rect.width() <= 72.1,
                "toolbar expanded the compact sidebar to {}",
                response.response.rect.width()
            );
        });
    }
}

